#!/usr/bin/env node
// GENERATED by system3-meta src/agents-md.mjs (profile system3-sqlite) from src/branch-check.mjs; regenerate, never hand-edit.
// The Codex branch check (system3-meta src/branch-check.mjs; a copy is generated into each company as
// codex-branch-check.mjs by src/agents-md.mjs). It makes two of AGENTS.md's rules loud in CI, on `codex/*` branches only
// (any other branch, a human's own, is skipped):
//   1. no commit since the base carries the deploy marker (the word deploy in square brackets) in its message, and
//      neither does the pull request's title or body;
//   2. the branch merges or integrates no other branch or pull request that the pull request body does not name:
//      a merge commit whose other parent is not already in the base, or a commit whose message says it integrates,
//      merges or cherry-picks a pull request (#N) or carries a "cherry picked from" trailer;
//   3. no commit is authored under a role's name (a role in .claude/agents/, or founder, owner and the like): commits
//      from Codex carry Codex's identity.
// Usage: node codex-branch-check.mjs <repo> <base> [--branch=<name>] [--title=<text>] [--body-file=<file>]
//   The branch defaults to $BRANCH, then $GITHUB_HEAD_REF, then the checked-out branch; the title and body to
//   $PR_TITLE and $PR_BODY. CI: check out the pull request's head with fetch-depth 0 and pass origin/<base>.
// Exit 0: clean or skipped; 1: a rule is broken (each problem printed, as a GitHub error annotation in Actions); 2: usage.
// Node's standard library and git only.
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const MARKER = /\[\s*deploy\s*\]/i;
const VERB = /\b(integrat\w*|merg\w*|cherry[- ]?pick\w*|rebas\w*|pull(?:ed|s|ing)? in|bring(?:s|ing)? in|brought in)\b/i;
const PR_REF = /(?:#|\bPR\s*#?|\bpull request\s*#?)(\d+)\b/gi;
const ROLE_WORDS = ["founder", "owner", "author", "chief-of-staff", "release-manager", "evaluation-steward", "coordinator", "managing-editor"];

function git(repo, ...a) {
  const r = spawnSync("git", ["-C", repo, ...a], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  return { ok: r.status === 0, out: (r.stdout ?? "").replace(/\n$/, ""), err: (r.stderr ?? "").trim() };
}
const norm = (s) => String(s ?? "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");

/** The role names a commit author must not use: .claude/agents/*.md (file names and `name:`) plus ROLE_WORDS. */
export function roleNames(repo) {
  const set = new Set(ROLE_WORDS);
  const d = path.join(repo, ".claude", "agents");
  let files = [];
  try { files = fs.readdirSync(d).filter((f) => f.endsWith(".md")); } catch { /* no roles */ }
  for (const f of files) {
    set.add(norm(f.slice(0, -3)));
    try { const n = /^name:\s*(.+)$/m.exec(fs.readFileSync(path.join(d, f), "utf8"))?.[1]; if (n) set.add(norm(n.replace(/^["']|["']$/g, ""))); } catch { /* unreadable */ }
  }
  set.delete("");
  return set;
}

/** Is `name` (a branch, "#N" or a commit) named in the pull request body? */
function named(body, name) {
  if (!body || !name) return false;
  if (/^#\d+$/.test(name)) return new RegExp(`(^|[^\\w])${name}(?!\\d)`).test(body) || new RegExp(`/pull/${name.slice(1)}(?!\\d)`).test(body);
  if (/^[0-9a-f]{40}$/.test(name)) return [...body.matchAll(/\b[0-9a-f]{7,40}\b/g)].some((m) => name.startsWith(m[0]));
  return body.includes(name);
}

/** The names a merged parent goes by: the branch or pull request in the merge's subject, and refs pointing at it. */
function mergedNames(repo, subject, parent) {
  const names = new Set();
  let m;
  if ((m = /^Merge pull request #(\d+) from [^/\s]+\/(\S+)/.exec(subject))) { names.add(`#${m[1]}`); names.add(m[2]); }
  if ((m = /^Merge (?:remote-tracking )?branch '([^']+)'/.exec(subject))) names.add(m[1].replace(/^(origin|upstream)\//, ""));
  if ((m = /\(#(\d+)\)\s*$/.exec(subject))) names.add(`#${m[1]}`);
  for (const r of git(repo, "for-each-ref", "--points-at", parent, "--format=%(refname:short)").out.split("\n").filter(Boolean)) names.add(r.replace(/^(origin|upstream)\//, ""));
  return [...names];
}

/** Check a branch: { skipped?, branch, commits, problems[] }. */
export function checkBranch(repo, base, opt = {}) {
  const env = opt.env ?? process.env;
  const branch = opt.branch ?? (env.BRANCH || env.GITHUB_HEAD_REF || git(repo, "rev-parse", "--abbrev-ref", "HEAD").out);
  if (!/^codex\//.test(branch)) return { skipped: true, branch, commits: 0, problems: [] };
  const title = opt.title ?? env.PR_TITLE ?? "", body = opt.body ?? env.PR_BODY ?? null;
  const problems = [];
  if (!git(repo, "rev-parse", "--verify", "--quiet", `${base}^{commit}`).ok) return { branch, commits: 0, problems: [`the base "${base}" is not a commit here (in CI, check out with fetch-depth: 0)`] };
  const baseName = base.replace(/^(refs\/remotes\/)?(origin|upstream)\//, "");
  if (MARKER.test(title)) problems.push("the pull request title carries the deploy marker: deploys are the founder's, never Codex's");
  if (body && MARKER.test(body)) problems.push("the pull request body carries the deploy marker: deploys are the founder's, never Codex's");
  const log = git(repo, "log", "--format=%H%x1f%P%x1f%an%x1f%ae%x1f%B%x1e", `${base}..HEAD`);
  if (!log.ok) return { branch, commits: 0, problems: [`git log ${base}..HEAD failed: ${log.err}`] };
  const commits = log.out.split("\x1e").map((s) => s.replace(/^\n/, "")).filter(Boolean).map((s) => { const [sha, parents, an, ae, msg] = s.split("\x1f"); return { sha, parents: parents.split(" ").filter(Boolean), an, ae, msg: msg ?? "" }; });
  const roles = roleNames(repo);
  const noBody = body === null ? " (no pull request body was given: pass $PR_BODY or --body-file)" : "";
  for (const c of commits) {
    const short = c.sha.slice(0, 9), subject = c.msg.split("\n")[0];
    if (MARKER.test(c.msg)) problems.push(`${short} carries the deploy marker in its message ("${subject}"): deploys are the founder's; reword the commit`);
    const who = [norm(c.an), norm(c.ae.split("@")[0])].find((n) => roles.has(n));
    if (who) problems.push(`${short} is authored as "${c.an} <${c.ae}>", the role "${who}": commits from Codex carry Codex's own identity, never a role's or a person's`);
    for (const p of c.parents.slice(1)) {
      if (git(repo, "merge-base", "--is-ancestor", p, base).ok) continue; // the base itself, merged in to stay current
      const names = mergedNames(repo, subject, p);
      if (names.includes(baseName)) continue;
      if (names.some((n) => named(body, n)) || named(body, p)) continue;
      problems.push(`${short} merges ${names.length ? names.join(", ") : `commit ${p.slice(0, 9)}`} into the branch, and the pull request body does not name it${noBody}: integrate other branches or pull requests only when the task names them, and say so at the top of the pull request`);
    }
    if (c.parents.length < 2) {
      const prs = VERB.test(subject) ? [...subject.matchAll(PR_REF)].map((m) => `#${m[1]}`) : [];
      const picked = [...c.msg.matchAll(/cherry picked from commit ([0-9a-f]{7,40})/gi)].map((m) => m[1]);
      const missing = [...prs.filter((n) => !named(body, n)), ...picked.filter((s) => !named(body, s) && !git(repo, "merge-base", "--is-ancestor", s, base).ok)];
      if (missing.length) problems.push(`${short} integrates ${missing.join(", ")} ("${subject}"), and the pull request body does not name it${noBody}: integrate other branches or pull requests only when the task names them, and say so at the top of the pull request`);
    }
  }
  return { branch, commits: commits.length, problems };
}

export function main(argv, env = process.env) {
  const args = argv.filter((a) => !a.startsWith("--")), opt = { env };
  for (const a of argv) {
    let m;
    if ((m = /^--branch=(.*)$/.exec(a))) opt.branch = m[1];
    else if ((m = /^--title=(.*)$/s.exec(a))) opt.title = m[1];
    else if ((m = /^--body-file=(.*)$/.exec(a))) { try { opt.body = fs.readFileSync(m[1], "utf8"); } catch (e) { console.error(`branch-check: ${e.message}`); return 2; } }
  }
  const [repo, base] = args;
  if (!repo || !base) { console.error("usage: node codex-branch-check.mjs <repo> <base> [--branch=<name>] [--title=<text>] [--body-file=<file>]"); return 2; }
  const r = checkBranch(repo, base, opt);
  if (r.skipped) { console.log(`branch-check: ${r.branch || "(no branch)"} is not a codex/* branch; skipped`); return 0; }
  if (r.problems.length) {
    for (const p of r.problems) console.error(env.GITHUB_ACTIONS ? `::error title=Codex branch check::${p}` : `branch-check: ${p}`);
    console.error(`branch-check: ${r.branch}: ${r.problems.length} problem(s) in ${r.commits} commit(s) since ${base} (AGENTS.md, "How work lands: pull requests only")`);
    return 1;
  }
  console.log(`branch-check: ${r.branch}: ${r.commits} commit(s) since ${base}, clean`);
  return 0;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv.slice(2)));
